begin;
set local lock_timeout='5s';set local statement_timeout='30s';set local standard_conforming_strings=on;
create temporary table cartridge_restore_plan(payload jsonb) on commit drop;
insert into cartridge_restore_plan values('[{"id":4903,"sku":"6365C002","brand":"Canon","name":"Картридж Canon 075 MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw Black (1400 стор.) (6365C002)","source":"https://www.canon.co.uk/store/store/canon-075-black-toner-cartridge/6365C002/","protectDescription":false,"before":{"specifications":{},"description":"~1400 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, чорний","manual_overrides":{}},"after":{"specifications":{"Тип витратного матеріалу":"Тонер-картридж","Серія картриджа":"075","Колір друку":"Чорний","Ресурс друку":"До 1400 сторінок","Ємність картриджа":"Стандартна","Сумісний бренд":"Canon","Сумісні пристрої":"Canon i-SENSYS MF664Cdw; MF667Cdw; LBP646Cdw; LBP647Cdw"},"description":"~1400 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, чорний","manual_overrides":{"verified_specifications":true}}},{"id":4904,"sku":"6364C002","brand":"Canon","name":"Картридж Canon 075C MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw Cyan (1300 стор.) (6364C002)","source":"https://www.canon.co.uk/store/canon-075-cyan-toner-cartridge/6364C002/","protectDescription":false,"before":{"specifications":{},"description":"~1300 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, блакитний","manual_overrides":{}},"after":{"specifications":{"Тип витратного матеріалу":"Тонер-картридж","Серія картриджа":"075","Колір друку":"Блакитний (Cyan)","Ресурс друку":"До 1300 сторінок","Ємність картриджа":"Стандартна","Сумісний бренд":"Canon","Сумісні пристрої":"Canon i-SENSYS MF664Cdw; MF667Cdw; LBP646Cdw; LBP647Cdw"},"description":"~1300 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, блакитний","manual_overrides":{"verified_specifications":true}}},{"id":4905,"sku":"6369C002","brand":"Canon","name":"Картридж Canon 075H MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw Black (3500 стор.) (6369C002)","source":"https://www.canon.co.uk/store/canon-075-h-high-yield-black-toner-cartridge/6369C002/","protectDescription":false,"before":{"specifications":{},"description":"~3500 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, чорний","manual_overrides":{}},"after":{"specifications":{"Тип витратного матеріалу":"Тонер-картридж","Серія картриджа":"075H","Колір друку":"Чорний","Ресурс друку":"До 3500 сторінок","Ємність картриджа":"Підвищена","Сумісний бренд":"Canon","Сумісні пристрої":"Canon i-SENSYS MF664Cdw; MF667Cdw; LBP646Cdw; LBP647Cdw"},"description":"~3500 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, чорний","manual_overrides":{"verified_specifications":true}}},{"id":4906,"sku":"6368C002","brand":"Canon","name":"Картридж Canon 075H MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw Cyan (2500 стор.) (6368C002)","source":"https://www.canon.co.uk/store/canon-075-h-high-yield-cyan-toner-cartridge/6368C002/","protectDescription":false,"before":{"specifications":{},"description":"~2500 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, блакитний","manual_overrides":{}},"after":{"specifications":{"Тип витратного матеріалу":"Тонер-картридж","Серія картриджа":"075H","Колір друку":"Блакитний (Cyan)","Ресурс друку":"До 2500 сторінок","Ємність картриджа":"Підвищена","Сумісний бренд":"Canon","Сумісні пристрої":"Canon i-SENSYS MF664Cdw; MF667Cdw; LBP646Cdw; LBP647Cdw"},"description":"~2500 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, блакитний","manual_overrides":{"verified_specifications":true}}}]'::jsonb);
do $restore$
declare item jsonb;current_row jsonb;saved jsonb;after_row jsonb;
begin
 perform id from public.products where id in (4903,4904,4905,4906) order by id for update;
 for item in select value from cartridge_restore_plan,jsonb_array_elements(payload) loop
  select to_jsonb(p) into current_row from public.products p where id=(item->>'id')::bigint;
  if current_row is null or current_row->>'sku' is distinct from item->>'sku' or current_row->>'brand' is distinct from item->>'brand' or current_row->>'name' is distinct from item->>'name' then raise exception 'Identity changed';end if;
  if current_row->'specifications' is distinct from item->'after'->'specifications' or current_row->'description' is distinct from item->'after'->'description' or current_row->'manual_overrides' is distinct from item->'after'->'manual_overrides' then raise exception 'Card changed since enrichment';end if;
  select before_row into saved from technoroom_maintenance.product_repair_backup where operation='canon-075-content-20261027' and product_id=(item->>'id')::bigint;
  if saved is null then raise exception 'Backup missing';end if;
  perform set_config('technoroom.import_write','false',true);
  update public.products set specifications=saved->'specifications' where id=(item->>'id')::bigint;
  select to_jsonb(p) into after_row from public.products p where id=(item->>'id')::bigint;
  if after_row->'specifications' is distinct from saved->'specifications' or (after_row-array['specifications','updated_at']) is distinct from (current_row-array['specifications','updated_at']) then raise exception 'Unexpected restore side effect';end if;
 end loop;
end $restore$;
commit;
